SELECT DISTINCT ?item ?itemLabelEn ?itemLabelRu ?elevation_m ?area_sqkm ?length_km WHERE {
      ?item wdt:P31/wdt:P279* wd:Q8514 .
      ?item wdt:P17 wd:Q159 .
      ?item rdfs:label ?itemLabelEn FILTER(LANG(?itemLabelEn) = "en") .
      OPTIONAL { ?item rdfs:label ?itemLabelRu FILTER(LANG(?itemLabelRu) = "ru") . }
    }
    LIMIT 701

