      ?related wdt:P31 wd:Q4022 .
      { ?item wdt:P30 wd:Q49 . }
      UNION
      { ?item wdt:P17 ?itemCountryForContinent . ?itemCountryForContinent wdt:P30 wd:Q49 . }

      {
        ?item p:P2046 ?itemMetricStatement .
        ?itemMetricStatement psv:P2046 ?itemMetricValue .
        ?itemMetricValue wikibase:quantityAmount ?itemMetricAmount .
        ?itemMetricValue wikibase:quantityUnit ?itemMetricUnit .
        BIND((IF(?itemMetricUnit = wd:Q712226, xsd:decimal(?itemMetricAmount), IF(?itemMetricUnit = wd:Q25343, xsd:decimal(?itemMetricAmount) / 1000000, IF(?itemMetricUnit = wd:Q35852, xsd:decimal(?itemMetricAmount) / 100, xsd:decimal(?itemMetricAmount))))) AS ?area_sqkm) .
      }
      FILTER(?area_sqkm <= 500) .

      {
        ?related p:P2043 ?relatedMetricStatement .
        ?relatedMetricStatement psv:P2043 ?relatedMetricValue .
        ?relatedMetricValue wikibase:quantityAmount ?relatedMetricAmount .
        ?relatedMetricValue wikibase:quantityUnit ?relatedMetricUnit .
        BIND((IF(?relatedMetricUnit = wd:Q828224, xsd:decimal(?relatedMetricAmount), IF(?relatedMetricUnit = wd:Q11573, xsd:decimal(?relatedMetricAmount) / 1000, IF(?relatedMetricUnit = wd:Q3710, xsd:decimal(?relatedMetricAmount) * 0.0003048, xsd:decimal(?relatedMetricAmount))))) AS ?length_km) .
      }
      FILTER(?length_km >= 500) .
}

